import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"34、【大壯】 乾下震上","description":"周易尚氏學 - 34、【大壯】 乾下震上","frontmatter":{"title":"34、【大壯】 乾下震上","description":"周易尚氏學 - 34、【大壯】 乾下震上"},"headers":[],"relativePath":"classics/shangshi/039.md","filePath":"classics/shangshi/039.md"}'),s={name:"classics/shangshi/039.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_34、【大壯】-乾下震上" tabindex="-1">34、【大壯】 乾下震上 <a class="header-anchor" href="#_34、【大壯】-乾下震上" aria-label="Permalink to “34、【大壯】 乾下震上”">​</a></h1><p>雜卦雲。大壯則止。序卦雲。物不可以終壯。故授之以晉。晉者進也。是亦訓為止。故與進對文。太玄擬為格。格阻也。亦止也。又擬為夷。夷傷也。故馬虞訓壯為傷。吳先生曰。傷則必止。二義相因。按說卦震為蕃。蕃有閉義。詩四國於蕃。箋雲蕃屏也。周禮大司徒蕃樂。杜子春讀蕃為藩。謂藩閉樂器而不用。是蕃與藩通。大壯之所以為止者。以震藩屏閉在前也。四不應初。二三遇敵。下陽全為四所格阻。故日曰貞。言利於貞定不動也。即止也。不止則傷。四五兩爻是也。鄭王謂為強盛。然注莫古於十翼。莫精於太玄。皆不如是言。疑非易本旨。</p><p>彖曰。大壯。大者壯也。剛以動。故壯。大壯利貞。大者正也。正大而大地之情可見矣。</p><p>大謂乾。乾在下為四所格。故曰大者壯也。蓋剛宜靜。剛而動必多阻格。釋壯之故也。利貞者。貞定。乾象傳雲。各正性命。保合太和。乃利貞。天地之情。本如是也。</p><p>象曰。雷在天上。大壯。君子以非禮弗履。</p><p>震為履。震履乾。即卑履尊。非禮甚矣。陸績曰。君子見卑履尊。終必消除。故以為戒。大象每相反為義。此其一也。</p><p>初九。壯於趾。徵兇。</p><p>有年初應在四。四震為趾。乃四亦陽。初失應。故壯於趾。言趾有所阻格也。又二三亦陽。陽遇陽則窒。故徵兇。有二說文有不宜有也。春秋傳日月有食之是也。依說文。有孚者。謂不宜於有也。即不孚也。正與象辭孚窮之義合也。</p><h3 id="象曰。壯於趾。其孚窮也。" tabindex="-1">象曰。壯於趾。其孚窮也。 <a class="header-anchor" href="#象曰。壯於趾。其孚窮也。" aria-label="Permalink to “象曰。壯於趾。其孚窮也。”">​</a></h3><p>初得敵。無應。故孚窮。</p><p>九二。貞吉。</p><p>二得中。故貞吉。與下貞歷為對文。</p><h3 id="象曰。九二貞吉。以中也。" tabindex="-1">象曰。九二貞吉。以中也。 <a class="header-anchor" href="#象曰。九二貞吉。以中也。" aria-label="Permalink to “象曰。九二貞吉。以中也。”">​</a></h3><p>二承乘皆陽。得敵。似不吉。然而言者。以位中也。</p><p>九三。小人用壯。君子用罔。貞歷。羝羊觸藩。贏其角。</p><p>三應在上。小人謂上六。君子謂三。乃上六慾應三。而為五所格。故用壯。三欲應上。而為四所格。故用罔。目無也。言三上皆失其用也。故卜問歷。中爻互兌。故曰羊。四震為藩。贏纏繞也。三在下卦之上。於交象為角。羝羊觸藩。贏其角者。言三欲上升。為九四所阻格。若羝羊以角觸藩而不能決。角反為藩所困也。荀爽以五為角。五為角。則藩已決矣。胡有贏象哉。震藩象。易林乾之豐雲。藩屏周衛。同人之師雲。藩屏湯武。皆以震為藩。而藩與蕃通。說卦震為蕃。即易林所本也。</p><h3 id="象曰。小人用壯。君子罔也。" tabindex="-1">象曰。小人用壯。君子罔也。 <a class="header-anchor" href="#象曰。小人用壯。君子罔也。" aria-label="Permalink to “象曰。小人用壯。君子罔也。”">​</a></h3><p>罔猶否也。</p><p>九四。貞吉。悔亡。藩決不贏。壯於大典之輹。</p><p>四前監重陰利往。故貞吉無悔。故藩決不贏。震為輿。為輹。象曰尚往。是四往五也。四往五。震象毀。而兌為毀折。故曰壯於大輿之輹。蓋卦以止為義。藩決則進。進則有傷。五爻喪羊相因而至矣。虞翻因不知輹象。氦輹為腹。非。</p><h3 id="象曰。藩決不贏。尚往也。尚往言上進居五。" tabindex="-1">象曰。藩決不贏。尚往也。尚往言上進居五。 <a class="header-anchor" href="#象曰。藩決不贏。尚往也。尚往言上進居五。" aria-label="Permalink to “象曰。藩決不贏。尚往也。尚往言上進居五。”">​</a></h3><p>六五。喪羊於易。無悔。</p><p>兌為羊。兌毀折故喪羊。易。釋文雲。陸作場。謂疆場也。古文往往如是。說文場田畔也。詩小雅。疆場有瓜。喪羊於場。言喪羊于田畔也。諸家作難易解。不辭甚矣。惟場象無有詳者。按震為阪。說文阪坡也。山協也。詩小雅。瞻彼阪田。場既為田畔。疑仍震象也。然雖喪羊。下有應得中。亦無悔也。</p><h3 id="象曰。喪羊於易。位不當也。" tabindex="-1">象曰。喪羊於易。位不當也。 <a class="header-anchor" href="#象曰。喪羊於易。位不當也。" aria-label="Permalink to “象曰。喪羊於易。位不當也。”">​</a></h3><p>位不當。釋喪羊之故也。</p><p>上六。羝羊觸藩。不能退。不能遂。無攸利。艱則吉。</p><p>卦全體兌象。故仍曰抵羊。上欲應三。而為五所格。五亦陰得故。三之藩在四。上之藩在五。故退欲來三。為藩所阻。進欲前往。而道已窮。故不能退不能遂。巽為利。巽伏故無攸利。然上當位有應。艱貞自守。終吉也。</p><h3 id="象曰。不能退。不能遂。不詳也。艱則吉。咎不長也。" tabindex="-1">象曰。不能退。不能遂。不詳也。艱則吉。咎不長也。 <a class="header-anchor" href="#象曰。不能退。不能遂。不詳也。艱則吉。咎不長也。" aria-label="Permalink to “象曰。不能退。不能遂。不詳也。艱則吉。咎不長也。”">​</a></h3><p>釋文雲。詳審也。審慎也。言不能退不能遂之故。咎在不慎審於始而妄動也。鄭虞王肅王弼皆釋詳為善。於義亦通。三上為正應。終必和合。故曰咎不長。</p>',29)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
